\title{Separable Rank of Bivariate Targets and the EML Outer Count\\
in Kolmogorov--Arnold Superpositions}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
The Kolmogorov--Arnold superposition theorem guarantees that every continuous
function $f:[0,1]^n\to\R$ is a finite sum of $2n+1$ outer univariate functions
applied to sums of inner univariate functions. While the theorem fixes the
number of \emph{inner} functions, it says nothing about the number of
\emph{outer} terms required by a given target. We introduce the
\emph{separable rank} $\SepRankLE(f,r)$ of a bivariate target
$f:\R\times\R\to\R$ --- the property that $f(x,y)=\sum_{k<r} a_k(x)\,b_k(y)$ ---
which is exactly the number of outer functions in a finite sum-of-products
Kolmogorov--Arnold superposition. When the factors are positive, every term is
an EML (exp--log--multiply) expression
$a_k(x)b_k(y)=\exp(\log a_k(x)+\log b_k(y))$, so separable rank equals the EML
outer $\exp$ count. We prove: (1) separable rank $\le 1$ is exactly
multiplicative separability; (2) a matrix sampling lower bound --- any
$m\times m$ evaluation matrix of a separable-rank-$\le r$ target has matrix rank
$\le r$, so one invertible sample forces $m\le r$; (3) the additive target
$x+y$ has separable rank exactly $2$; (4) the power-sum family
$p_N(x,y)=\sum_{k<N}x^k y^k$ has separable rank exactly $N$ (via a Vandermonde
sample $VV^\top$ with $\det=(\det V)^2\ne 0$), so the EML outer count is
unbounded even though the inner count is capped at $2n+1$. All results have been
formally verified in Lean~4.
\end{abstract}

\section{Introduction}

\subsection{Background}
Hilbert's thirteenth problem asked whether certain continuous functions of
several variables are genuinely irreducible to functions of fewer variables.
Kolmogorov (1956) and Arnold (1957) answered negatively in the strongest form.

\begin{theorem}[Kolmogorov--Arnold superposition]
For every $n\ge 2$ there exist continuous functions
$\psi_{q,p}:[0,1]\to\R$ ($0\le q\le 2n$, $1\le p\le n$) such that every
continuous $f:[0,1]^n\to\R$ can be written as
\[
f(x_1,\dots,x_n)=\sum_{q=0}^{2n}\Phi_q\!\left(\sum_{p=1}^{n}\psi_{q,p}(x_p)\right)
\]
for suitable continuous outer functions $\Phi_q:\R\to\R$.
\end{theorem}

For $n=2$ the outer count is $2n+1=5$. The theorem is an existence statement; it
does not quantify how many outer terms a specific target needs. We study this
through a computable invariant.

\subsection{EML functions}
An \emph{EML} function is a finite composition of $\exp$, $\log$,
multiplication, addition, and constants. We work with an inductive term algebra
\texttt{EMLTerm} (constructors \texttt{var}, \texttt{const}, \texttt{add},
\texttt{mul}, \texttt{expOf}, \texttt{logOf}) and an evaluation map
$\eval:\texttt{EMLTerm}\to(\R\to\R)$. The distinguished outer term is
$\texttt{outerExp}=\texttt{expOf var}$ with $\eval(\texttt{outerExp})(u)=\exp u$,
and the inner term is $\texttt{innerLog}=\texttt{logOf var}$ with
$\eval(\texttt{innerLog})(t)=\log t$. For $x>0$,
$\eval(\texttt{expOf}(\texttt{logOf var}))(x)=\exp(\log x)=x$.

\subsection{The product as a rank-one EML superposition}
On the open positive quadrant,
\[
x\cdot y=\exp(\log x+\log y)
=\eval(\texttt{outerExp})\big(\eval(\texttt{innerLog})(x)+\eval(\texttt{innerLog})(y)\big),
\]
a Kolmogorov--Arnold superposition with a single outer EML term. This is not
globally valid since $\exp>0$; globally one uses the polarization identity
$x\cdot y=\tfrac14(x+y)^2-\tfrac14(x-y)^2$, a two-term representation. The
contrast motivates a quantitative notion of outer count.

\section{Definitions}
Throughout, $f,g:\R\to\R\to\R$ are bivariate targets and $r,m,N\in\N$.

\begin{definition}[Multiplicative separability]
$\MulSeparable(f)$ holds if there exist $a,b:\R\to\R$ with $f(x,y)=a(x)\,b(y)$
for all $x,y$.
\end{definition}

\begin{definition}[Cross-multiplicative identity]
$\CrossMul(f)$ holds if $f(x,y)\,f(x',y')=f(x,y')\,f(x',y)$ for all
$x,y,x',y'$. Background fact: $\MulSeparable(f)\iff\CrossMul(f)$ once $f$ has a
nonzero value.
\end{definition}

\begin{definition}[Separable rank]
$\SepRankLE(f,r)$ holds if there exist $a,b:\mathrm{Fin}\,r\to(\R\to\R)$ with
\[
f(x,y)=\sum_{k=0}^{r-1} a_k(x)\,b_k(y)\qquad\text{for all }x,y.
\]
The exact separable rank is the least such $r$. When each $a_k,b_k>0$ it equals
the number of EML \texttt{outerExp} terms, since
$a_k(x)b_k(y)=\exp(\log a_k(x)+\log b_k(y))$.
\end{definition}

\begin{definition}[Evaluation matrix]
For points $x,y:\mathrm{Fin}\,m\to\R$, the evaluation matrix
$M\in\R^{m\times m}$ has $M_{ij}=f(x_i,y_j)$.
\end{definition}

\begin{definition}[Power-sum target]
For $N\in\N$, $\;p_N(x,y)=\sum_{k=0}^{N-1} x^k\,y^k$.
\end{definition}

\section{Main Results}

\subsection{Rank one equals multiplicative separability}
\begin{theorem}[\texttt{mulSeparable\_iff\_sepRankLE\_one}]
For every bivariate $f$, $\;\MulSeparable(f)\iff\SepRankLE(f,1)$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) If $f(x,y)=a(x)b(y)$, take $a_0=a,b_0=b$; the one-term sum is
$a_0(x)b_0(y)$. ($\Leftarrow$) A rank-$\le1$ representation has a single index,
so $\sum_{k<1}a_k(x)b_k(y)=a_0(x)b_0(y)$, exhibiting $f$ as a product.
\end{proof}

\subsection{The matrix sampling lower bound}
\begin{theorem}[\texttt{sample\_rank\_le}]
If $\SepRankLE(f,r)$, then for all $m$ and all $x,y:\mathrm{Fin}\,m\to\R$,
$\rank(M)\le r$ where $M_{ij}=f(x_i,y_j)$.
\end{theorem}
\begin{proof}[Proof sketch]
With $f(x,y)=\sum_{k<r}a_k(x)b_k(y)$, set $A_{ik}=a_k(x_i)$ and
$B_{kj}=b_k(y_j)$. Then $(AB)_{ij}=\sum_{k<r}a_k(x_i)b_k(y_j)=M_{ij}$, so
$M=AB$ and $\rank(M)\le\rank(A)\le r$.
\end{proof}

\begin{corollary}[\texttt{sepRankLE\_ge\_of\_det\_ne\_zero}]
If $\SepRankLE(f,r)$ and some $m\times m$ evaluation matrix $M$ has
$\det M\ne 0$, then $m\le r$.
\end{corollary}
\begin{proof}[Proof sketch]
$\det M\ne 0$ makes $M$ invertible, hence $\rank(M)=m$; apply the previous
theorem.
\end{proof}

\subsection{The product: rank one}
\begin{theorem}[\texttt{mul\_sepRankLE\_one}]
The product $f(x,y)=x\cdot y$ satisfies $\SepRankLE(f,1)$ (take $a_0=b_0=\mathrm{id}$).
\end{theorem}

\subsection{The sum: rank exactly two}
\begin{theorem}[\texttt{add\_sepRankLE\_two}]
$f(x,y)=x+y$ satisfies $\SepRankLE(f,2)$ via $x+y=x\cdot 1+1\cdot y$.
\end{theorem}

\begin{theorem}[\texttt{add\_not\_sepRankLE\_one}]
$f(x,y)=x+y$ does not satisfy $\SepRankLE(f,1)$; its separable rank is exactly
$2$.
\end{theorem}
\begin{proof}[Proof sketch]
Sample at $x,y\in\{0,1\}$:
$M=\left(\begin{smallmatrix}0&1\\1&2\end{smallmatrix}\right)$ with
$\det M=-1\ne 0$. Rank $\le1$ would give $2\le1$ by the corollary, a
contradiction.
\end{proof}

\subsection{The power-sum family: unbounded rank}
\begin{theorem}[\texttt{powerSum\_sepRankLE}]
For every $N$, $\SepRankLE(p_N,N)$ via $a_k(x)=x^k$, $b_k(y)=y^k$.
\end{theorem}

\begin{theorem}[\texttt{powerSum\_rank\_ge}]
If $\SepRankLE(p_N,r)$ then $N\le r$; the separable rank of $p_N$ is exactly $N$.
\end{theorem}
\begin{proof}[Proof sketch]
Sample at $t_i=i$, $i=0,\dots,N-1$. Then
$M_{ij}=\sum_{k<N}i^k j^k=(VV^\top)_{ij}$ for the Vandermonde matrix
$V_{ik}=i^k$. Distinct points give
$\det V=\prod_{i<j}(t_j-t_i)\ne 0$, so $\det M=(\det V)^2\ne 0$ and $N\le r$ by
the corollary.
\end{proof}

\begin{corollary}[Unbounded EML outer count]
$\sup_N\SepRank(p_N)=\infty$: there is no fixed bound on the number of EML outer
$\exp$ terms in a sum-of-products Kolmogorov--Arnold representation, although the
number of inner functions is capped at $2n+1$.
\end{corollary}

\subsection{The EML bridge}
When all factors are positive, each separable term is a single
\texttt{outerExp} of a sum of inner logs:
$a_k(x)b_k(y)=\exp(\log a_k(x)+\log b_k(y))$ (statement
\texttt{sepRank\_pos\_eml}). Thus separable rank equals the EML outer count.

\section{Algorithms}

\subsection{Separable-rank lower bound via sampling}
\begin{verbatim}
function SEPARABLE_RANK_LOWER_BOUND(f, xs, ys):
    m  <- length(xs)            # = length(ys)
    M  <- matrix M[i][j] = f(xs[i], ys[j])
    d  <- det(M)
    if d != 0: return ("rank >= m", m)   # by Corollary
    else:      return ("inconclusive", None)
\end{verbatim}
By the sampling theorem the sampled rank never exceeds the true separable rank,
so any invertible $m\times m$ sample certifies $\SepRank(f)\ge m$.

\subsection{Vandermonde determinant detector}
\begin{verbatim}
function VANDERMONDE_DET(points):       # [t_0, ..., t_{N-1}]
    prod <- 1
    for j in 0 .. N-1:
        for i in 0 .. j-1:
            prod <- prod * (points[j] - points[i])
    return prod                          # = det V
\end{verbatim}
Then $\det(VV^\top)=(\det V)^2$; complexity $O(N^2)$ versus $O(N^3)$ for direct
elimination.

\section{Applications}
\begin{itemize}
\item \textbf{Kolmogorov--Arnold Networks.} Sum-of-products layers are
separable-rank decompositions; the power-sum bound gives a target-dependent
lower bound on exact-representation width.
\item \textbf{Low-rank function approximation.} The sampling bound is the
function-space analogue of Eckart--Young, guiding separation-of-variables and
tensor-train methods.
\item \textbf{Certified complexity.} The determinant corollary turns
``irreducibly complex'' into a single auditable computation.
\end{itemize}

\section{Discussion}
Kolmogorov--Arnold pins the number of inner univariate functions at $2n+1$, but
the outer EML count is unbounded across targets. The mechanism is uniform:
sampling a sum of products is a matrix factorization, so one linear-algebraic
principle controls every lower bound, with the Vandermonde matrix as the bridge.
The product's rank-one form is valid only on the positive quadrant; globally it
needs the rank-two polarization, a precise rank jump across the axes.

\section{Future Directions}
\begin{enumerate}
\item \textbf{Rank equals sup of sampled ranks.} Conjecture: the separable rank
equals the supremum over finite point sets of $\rank(M)$; the missing half is a
construction realizing the supremum.
\item \textbf{Multiplicativity for tensor products.} Conjecture:
$\SepRank(f\otimes g)=\SepRank(f)\,\SepRank(g)$, via Kronecker products.
\item \textbf{Polarization is rank-optimal globally.} Conjecture: over all of
$\R^2$, $x\cdot y$ has separable rank exactly $2$, a rank jump from $1$ (local)
to $2$ (global).
\item \textbf{Prescribed rank with bounded EML depth.} Conjecture: for each $N$
a target of separable rank $N$ with EML terms of exp/log-depth $\le1$, namely
$p_N(x,y)=\sum\exp(k\log x+k\log y)$ on the positive quadrant.
\end{enumerate}

\section{Conclusion}
We defined separable rank, identified it with the EML outer count of
sum-of-products Kolmogorov--Arnold superpositions, and showed it is governed
entirely by the matrix rank of sampled evaluation grids. The additive target has
rank exactly $2$ and the power-sum family realizes every rank $N$, proving the
outer count unbounded. The proofs reduce representation questions to elementary,
machine-checkable determinant computations.

